diff --git a/browser_ext/dart/src/browser_api_tools.dart b/browser_ext/dart/src/browser_api_tools.dart
index 37ef64cac..76fed0a93 100644
--- a/browser_ext/dart/src/browser_api_tools.dart
+++ b/browser_ext/dart/src/browser_api_tools.dart
@@ -198,22 +198,9 @@ List<BrowserToolSpec> browserApiToolSpecs() => List.unmodifiable(const [
     permissions: {'bookmarks'},
     tier: ApprovalTier.write,
   ),
-  // downloads.
-  BrowserToolSpec(
-    name: 'downloads_start',
-    permissions: {'downloads'},
-    tier: ApprovalTier.write,
-  ),
-  BrowserToolSpec(
-    name: 'downloads_search',
-    permissions: {'downloads'},
-    tier: ApprovalTier.read,
-  ),
-  BrowserToolSpec(
-    name: 'downloads_cancel',
-    permissions: {'downloads'},
-    tier: ApprovalTier.write,
-  ),
+  // downloads: the tools went with the `downloads` permission (gh-1630 —
+  // CWS rejects requested-but-unused permissions; a static review does not
+  // credit the Dart facade). Re-add WITH the real download feature only.
   // cookies.
   BrowserToolSpec(
     name: 'cookies_get',
@@ -1034,59 +1021,14 @@ final class BrowserApiToolSurface {
       ),

       // -------------------------------------------------------------------
-      // downloads
+      // downloads: removed with the `downloads` permission (gh-1630 — CWS
+      // Purple Potassium rejects requested-but-unused permissions, and a
+      // static review does not credit the Dart facade these tools rode).
+      // The OutboundKind.download gate stays: tabs_open still uses it, and
+      // the download tools come back through it WITH the real feature
+      // (gh-1630 F2 second tier). ChromeApi.downloads bindings stay for
+      // the same reason (dead code today, feature seam tomorrow).
       // -------------------------------------------------------------------
-      tool(
-        'downloads_start',
-        'Starts downloading a URL; the browser picks the filename unless '
-            'one is given. Returns the download id.',
-        {
-          'url': {'type': 'string', 'description': 'URL to download'},
-          'filename': {
-            'type': 'string',
-            'description': 'target filename relative to Downloads',
-          },
-        },
-        ['url'],
-        (args) async {
-          final url = _reqStr(args, 'url');
-          await _gateOutbound(OutboundKind.download, url);
-          final filename = _optStr(args, 'filename');
-          final id = await _chrome.downloads.download(
-            url: url,
-            filename: filename,
-          );
-          return ToolExecutionResult.text('started download $id from $url');
-        },
-      ),
-      tool(
-        'downloads_search',
-        'Lists downloads, optionally filtered by a substring over URL or '
-            'filename. Returns JSON download entries.',
-        {
-          'query': {
-            'type': 'string',
-            'description': 'substring filter (default: all)',
-          },
-        },
-        const [],
-        (args) async {
-          final query = _optStr(args, 'query');
-          final items = await _chrome.downloads.search(query: query);
-          return _json([for (final d in items) d.toJson()]);
-        },
-      ),
-      tool(
-        'downloads_cancel',
-        'Cancels an in-flight download.',
-        {'id': _intProp('download id')},
-        ['id'],
-        (args) async {
-          final id = _reqInt(args, 'id');
-          await _chrome.downloads.cancel(id);
-          return ToolExecutionResult.text('cancelled download $id');
-        },
-      ),

       // -------------------------------------------------------------------
       // cookies
diff --git a/flutter_app/lib/sandbox/web_interpreters_web.dart b/flutter_app/lib/sandbox/web_interpreters_web.dart
index 9c484c2b6..f8428355d 100644
--- a/flutter_app/lib/sandbox/web_interpreters_web.dart
+++ b/flutter_app/lib/sandbox/web_interpreters_web.dart
@@ -9,6 +9,8 @@ import 'dart:js_interop';
 import 'dart:typed_data';

 import 'package:fa/sandbox/sandbox_pip.dart';
+import 'package:fa/sandbox/web_interpreters_urls.dart'
+    show InterpreterAssets, interpreterAssets;

 /// Result of running a snippet in a browser-hosted interpreter.
 typedef InterpreterResult = ({bool available, String stdout, String stderr});
@@ -46,19 +48,17 @@ external JSPromise _fahSqlRun(String payloadJson);
 /// Browser-hosted Python (pyodide) and JavaScript (quickjs-emscripten)
 /// interpreters for the web sandbox.
 ///
-/// Both engines are loaded from public CDNs on first use and cached on
-/// `window`; nothing is bundled into the app. quickjs-emscripten is the same
+/// Engine scripts come from [interpreterAssets] (gh-1630 I3/I4): hosted
+/// web builds load them from public CDNs; the extension build resolves the
+/// SAME engines from the package-local, sha-verified `vendor/interpreters/`
+/// dir (no remote code — CWS Blue Argon; CSP forbids it anyway). Assets are
+/// cached on `window` after first use. quickjs-emscripten is the same
 /// QuickJS engine that runs as WASM on iOS/Android; pyodide is CPython
 /// compiled to WebAssembly for the browser.
 class WebInterpreters {
-  static const _quickJsCdn =
-      'https://cdn.jsdelivr.net/npm/quickjs-emscripten@0.31.0/dist/index.global.js';
-  static const _pyodideCdn =
-      'https://cdn.jsdelivr.net/pyodide/v0.26.4/full/pyodide.js';
-  static const _sqlJsCdn =
-      'https://cdn.jsdelivr.net/npm/sql.js@1.14.1/dist/sql-wasm.js';
-  static const _sqlJsDistBase =
-      'https://cdn.jsdelivr.net/npm/sql.js@1.14.1/dist/';
+  /// Engine script URLs for this build (CDN on the hosted web / Office
+  /// builds, package-local vendor dir in the extension build — gh-1630).
+  static InterpreterAssets get _assets => interpreterAssets();

   static Future<void>? _quickJsLoading;
   static Future<void>? _pyodideLoading;
@@ -116,22 +116,33 @@ class WebInterpreters {
   static Future<void> _ensureQuickJs() {
     return _quickJsLoading ??= _ensureScript(
       'fah-quickjs-cdn',
-      _quickJsCdn,
+      _assets.quickJsScript,
     ).then((_) => _injectHelperScript('fah-quickjs-runner', _qjsRunnerSource));
   }

   static Future<void> _ensurePyodide() {
+    // The runner gets an EXPLICIT indexURL in both builds: the web CDN
+    // full dir, or the package-local vendor dir — a wrong base fails the
+    // load loudly naming the missing asset instead of silently falling
+    // back to a remote default (gh-1630 E2).
+    final runner = _pyRunnerSource.replaceAll(
+      '__PYODIDE_INDEX_URL__',
+      _assets.pyodideIndex,
+    );
     return _pyodideLoading ??= _ensureScript(
       'fah-pyodide-cdn',
-      _pyodideCdn,
-    ).then((_) => _injectHelperScript('fah-pyodide-runner', _pyRunnerSource));
+      _assets.pyodideScript,
+    ).then((_) => _injectHelperScript('fah-pyodide-runner', runner));
   }

