      expect(assets.sqlJsScript,
          'https://cdn.jsdelivr.net/npm/sql.js@1.14.1/dist/sql-wasm.js');
      expect(
          assets.sqlJsDist, 'https://cdn.jsdelivr.net/npm/sql.js@1.14.1/dist/');
