Map<String, dynamic> parseManifest() {
  final raw = File('browser_ext/manifest.json').readAsStringSync();
  return jsonDecode(raw.replaceAll(RegExp(r'^\s*//.*$', multiLine: true), ''))
      as Map<String, dynamic>;
}

