  addTearDown(() => tmp.deleteSync(recursive: true));
  final f = File('${tmp.path}/blob')..writeAsBytesSync(bytes);
  return Process.runSync('sha256sum', [f.path]).stdout
      .toString()
      .split(' ')
      .first;
}

