  'quickjs',
  'pyodide',
  'sqljs',
  'webllm',
  'transformers',
  'litert',
};

/// Remote-code markers (AC1). The packaged tree must not carry ANY of
/// them — reviewers read the code, so the URL must not exist even for
/// never-executed paths (gh-1630 I1).
final remoteCodeMarker = RegExp(r'jsdelivr|unpkg|cdnjs|https://cdn\.');

/// browser_ext/ paths that are NOT packaged verbatim: build artifacts
/// (gitignored, regenerated by scripts/build_browser_ext.sh), the lock
/// itself (the sanctioned record OF the source URLs — the package carries
/// the fetched binaries), and the non-shipping source trees (the Dart
/// agent package ships only as the compiled sw/agent.js the zip scan
/// covers; node tests and Playwright specs never ship). Everything else
/// under browser_ext/ ships byte-for-byte and stays under this scan.
const browserExtBuildArtifacts = [
  'browser_ext/panel/app/',
  'browser_ext/sw/agent.js',
  'browser_ext/sw/agent.js.map',
  'browser_ext/sw/agent.js.deps',
  'browser_ext/vendor/',
  'browser_ext/vendor.lock.json',
  'browser_ext/dart/',
  'browser_ext/test/',
  'browser_ext/e2e/',
];

