+  /// honest `size_precheck: "unknown"` instead of guessing a size.
+  Future<int?> _downloadContentLength(String url) async {
+    final uri = Uri.tryParse(url);
+    if (uri == null ||
+        !(uri.scheme == 'http' || uri.scheme == 'https')) {
+      return null;
+    }
+    final client = FetchClient();
+    try {
